<script lang="ts">import {onMount} from 'svelte'; import {createApiClient} from '$lib/api/client'; type M={version:number;name:string;applied:boolean;dirty:boolean}; let migrations=$state<M[]>([]); let error=$state(''); onMount(async()=>{try{migrations=(await createApiClient().get<{migrations:M[]}>('/api/v1/admin/migrations')).migrations;}catch(e){error=e instanceof Error?e.message:'Could not load migrations';}});</script>
<svelte:head><title>Migrations | Betrayal Admin</title></svelte:head><main class="min-h-screen bg-slate-950 p-6 text-slate-100"><div class="mx-auto max-w-5xl"><h1 class="text-3xl font-semibold">Migrations</h1>{#if error}<p role="alert" class="mt-6 text-red-300">{error}</p>{:else}<div class="mt-8 space-y-2">{#each migrations as m (m.version)}<div class="flex justify-between border border-slate-700 p-3"><span>{m.version} · {m.name}</span><span>{m.dirty?'dirty':m.applied?'applied':'pending'}</span></div>{/each}</div>{/if}</div></main>
